-- Production policy definitions inspected 2026-11-05; schema-only regression fixture.
create policy profile_read on public.lti_profiles as PERMISSIVE for SELECT to authenticated using (((id = auth.uid()) OR (lti_role() = 'admin'::text) OR ((lti_role() = 'teacher'::text) AND (school_id = lti_school())) OR ((lti_role() = 'student'::text) AND (school_id = lti_school()) AND (role = 'teacher'::text) AND active)));
create policy profile_self_update on public.lti_profiles as PERMISSIVE for UPDATE to authenticated using ((id = auth.uid())) with check ((id = auth.uid()));
create policy feature_delete on public.lti_records as RESTRICTIVE for DELETE to authenticated using (lti_record_feature_enabled(kind, status, true));
create policy feature_insert on public.lti_records as RESTRICTIVE for INSERT to authenticated with check (lti_record_feature_enabled(kind, status, true));
create policy feature_read on public.lti_records as RESTRICTIVE for SELECT to authenticated using ((lti_record_feature_enabled(kind, status, false) AND ((kind <> 'papers'::text) OR (status <> '公開中'::text) OR lti_feature_enabled('みんなの論文'::text) OR (school_id = lti_school()))));
create policy feature_update on public.lti_records as RESTRICTIVE for UPDATE to authenticated using (lti_record_feature_enabled(kind, status, true)) with check (lti_record_feature_enabled(kind, status, true));
create policy record_delete on public.lti_records as PERMISSIVE for DELETE to authenticated using (((lti_role() = 'admin'::text) OR ((kind = ANY (ARRAY['references'::text, 'notes'::text])) AND (owner_id = auth.uid()) AND (lti_role() IS NOT NULL)) OR ((kind = 'submissions'::text) AND (lti_role() = 'student'::text) AND (student_id = (auth.uid())::text) AND (school_id = lti_school())) OR ((kind = ANY (ARRAY['assignments'::text, 'feedback'::text, 'paper_threads'::text])) AND (lti_role() = 'teacher'::text) AND (school_id = lti_school())) OR ((kind = 'papers'::text) AND (lti_role() = 'teacher'::text) AND (school_id = lti_school()) AND (status <> '公開中'::text))));
create policy record_insert on public.lti_records as PERMISSIVE for INSERT to authenticated with check (((owner_id = auth.uid()) AND (lti_role() IS NOT NULL) AND ((lti_role() = 'admin'::text) OR ((kind = ANY (ARRAY['references'::text, 'notes'::text])) AND (school_id = lti_school())) OR ((kind = ANY (ARRAY['papers'::text, 'paper_threads'::text, 'assignments'::text, 'feedback'::text])) AND (lti_role() = 'teacher'::text) AND (school_id = lti_school())) OR ((kind = 'submissions'::text) AND (lti_role() = 'student'::text) AND (school_id = lti_school()) AND (student_id = (auth.uid())::text)))));
create policy record_read on public.lti_records as PERMISSIVE for SELECT to authenticated using (lti_read_record(kind, owner_id, school_id, student_id, data));
create policy record_update on public.lti_records as PERMISSIVE for UPDATE to authenticated using (((lti_role() = 'admin'::text) OR ((kind = ANY (ARRAY['references'::text, 'notes'::text])) AND (owner_id = auth.uid()) AND (lti_role() IS NOT NULL)) OR ((kind = ANY (ARRAY['assignments'::text, 'papers'::text, 'paper_threads'::text, 'feedback'::text])) AND (lti_role() = 'teacher'::text) AND (school_id = lti_school())) OR ((kind = ANY (ARRAY['submissions'::text, 'feedback'::text])) AND (lti_role() = 'student'::text) AND (student_id = (auth.uid())::text) AND (school_id = lti_school())))) with check (((lti_role() = 'admin'::text) OR ((kind = ANY (ARRAY['references'::text, 'notes'::text])) AND (owner_id = auth.uid()) AND (lti_role() IS NOT NULL)) OR ((kind = ANY (ARRAY['assignments'::text, 'papers'::text, 'paper_threads'::text, 'feedback'::text])) AND (lti_role() = 'teacher'::text) AND (school_id = lti_school())) OR ((kind = ANY (ARRAY['submissions'::text, 'feedback'::text])) AND (lti_role() = 'student'::text) AND (student_id = (auth.uid())::text) AND (school_id = lti_school()))));
create policy school_admin on public.lti_schools as PERMISSIVE for ALL to authenticated using ((lti_role() = 'admin'::text)) with check ((lti_role() = 'admin'::text));
create policy school_read on public.lti_schools as PERMISSIVE for SELECT to authenticated using (((lti_role() = 'admin'::text) OR (id = lti_school())));
